const input=$input.first().json;
const contextual=input.contextualChangeSelection&&typeof input.contextualChangeSelection==='object'?input.contextualChangeSelection:null;
if(contextual&&['cancel','reschedule'].includes(String(contextual.changeType||''))&&typeof contextual.slotStart==='string'&&contextual.slotStart){return [{json:{...input,changeType:String(contextual.changeType),selectedReservationStart:contextual.slotStart,requestedTargetStart:String(contextual.requestedTargetStart||''),selectedReferenceDay:0,selectedReferenceMonth:0,selectedReferenceYear:0,selectedReferenceTime:'',selectedReferenceTimes:[],parseReason:'ok'}}];}
const message=typeof input.messageText==='string'?input.messageText.trim():'';
const from=typeof input.from==='string'?input.from.trim():'';
const normalized=message.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/\s+/g,' ').trim();
const empty={day:-1,month:-1,year:-1,hour:-1,minute:-1};const semantic=input.semanticReference&&typeof input.semanticReference==='object'?input.semanticReference:empty;const semanticTarget=input.semanticRescheduleTarget&&typeof input.semanticRescheduleTarget==='object'?input.semanticRescheduleTarget:empty;
const positive=value=>Number.isInteger(Number(value))&&Number(value)>0?Number(value):0;
const months={enero:1,febrero:2,marzo:3,abril:4,mayo:5,junio:6,julio:7,agosto:8,septiembre:9,setiembre:9,octubre:10,noviembre:11,diciembre:12};
const timeOf=(hour,minute,suffix)=>{let value=Number(hour);const period=String(suffix||'');if(/tarde|pm/.test(period)&&value<12)value+=12;else if(/manana|am/.test(period)&&value===12)value=0;else if(!period&&value>0&&value<8)value+=12;return value>=0&&value<=23?`${String(value).padStart(2,'0')}:${String(minute||'00').padStart(2,'0')}`:'';};
const direct=[];for(const match of message.matchAll(/(\d{4})-(\d{1,2})-(\d{1,2})\s*(?:a\s+las\s+)?([01]?\d|2[0-3]):([0-5]\d)|(\d{1,2})\/(\d{1,2})\/(\d{4})\s*(?:a\s+las\s+)?([01]?\d|2[0-3]):([0-5]\d)/gi)){const year=Number(match[1]||match[8]),month=Number(match[2]||match[7]),day=Number(match[3]||match[6]),time=`${String(match[4]||match[9]).padStart(2,'0')}:${match[5]||match[10]}`;direct.push({day,month,year,time});}
const natural=[];for(const match of normalized.matchAll(/(?:lunes|martes|miercoles|jueves|viernes|sabado|domingo)?\s*(\d{1,2})(?:\s+de\s+(enero|febrero|marzo|abril|mayo|junio|julio|agosto|septiembre|setiembre|octubre|noviembre|diciembre))?(?:\s+de\s+(\d{4}))?\s+(?:a\s+)?las\s+(\d{1,2})(?::([0-5]\d)|\s+y\s+(media))?\s*(de la tarde|de la manana|am|pm)?/gi)){const time=timeOf(match[4],match[5]||((match[6]||'')==='media'?'30':'00'),match[7]);if(time)natural.push({day:Number(match[1]),month:Number(months[match[2]]||0),year:Number(match[3]||0),time});}
const references=direct.length?direct:natural;
const lexicalTimes=[...normalized.matchAll(/(?:\ba\s+)?\blas\s+(\d{1,2})(?::([0-5]\d)|\s+y\s+(media))?\s*(de la tarde|de la manana|am|pm)?/gi)].map(match=>timeOf(match[1],match[2]||((match[3]||'')==='media'?'30':'00'),match[4])).filter(Boolean);
const selectionReference=/^(?:la|el)\s+(?:del|de la|de las)\s+.+/.test(normalized)||[semantic.day,semantic.month,semantic.year,semantic.hour,semantic.minute].some(value=>Number(value)>=0);
const hasCancel=/(?:\bcancel(?:ar|a|alo|ala)?\b|dar(?:la)? de baja|\bborrar\b|\beliminar\b|\banular\b|\bcancel\b|\bdelete\b|\bremove\b|\bcall off\b)/i.test(normalized)||selectionReference||(/\b(?:no voy a poder|no puedo|se me complica|no llego)\s+(?:ir|asistir)\b/.test(normalized)&&/\b(?:reunion|turno|meeting|call)\b/.test(normalized));
const hasReschedule=/\b(?:reprogramar|reprograma|reprogramalo|reprogramala|cambiar|cambia|pasar|pasala|pasarlo|reschedule)\b/i.test(normalized);
const named=normalized.match(/(?:lunes|martes|miercoles|jueves|viernes|sabado|domingo)?\s*(\d{1,2})\s+de\s+(enero|febrero|marzo|abril|mayo|junio|julio|agosto|septiembre|setiembre|octubre|noviembre|diciembre)(?:\s+de\s+(\d{4}))?/);const bareNamed=normalized.match(/\b(?:lunes|martes|miercoles|jueves|viernes|sabado|domingo)\s+(\d{1,2})\b/);const numeric=normalized.match(/\b(\d{1,2})\/(\d{1,2})(?:\/(\d{4}))?\b/);
const toInstant=(reference,inherited={})=>{const day=positive(reference.day),month=positive(reference.month)||positive(inherited.month),time=String(reference.time||'');if(!day||!month||!/^\d{2}:\d{2}$/.test(time))return '';let year=positive(reference.year)||positive(inherited.year)||new Date().getFullYear();const base=`${year}-${String(month).padStart(2,'0')}-${String(day).padStart(2,'0')}T${time}:00-03:00`;let date=new Date(base);if(!positive(reference.year)&&!positive(inherited.year)&&date.getTime()<Date.now()-86400000){year++;date=new Date(`${year}-${String(month).padStart(2,'0')}-${String(day).padStart(2,'0')}T${time}:00-03:00`);}return Number.isNaN(date.getTime())?'':date.toISOString();};
let changeType='unsupported',selectedReservationStart='',requestedTargetStart='',parseReason='unsupported_request',sourceReference={day:0,month:0,year:0,time:''};
if(hasReschedule){changeType='reschedule';sourceReference=references[0]||{day:positive(semantic.day),month:positive(semantic.month),year:positive(semantic.year),time:Number(semantic.hour)>=0?`${String(semantic.hour).padStart(2,'0')}:${String(Number(semantic.minute)>=0?semantic.minute:0).padStart(2,'0')}`:''};if(!sourceReference.time&&lexicalTimes.length)sourceReference.time=lexicalTimes[0];const targetReference=references.length>1?references[1]:{day:positive(semanticTarget.day),month:positive(semanticTarget.month),year:positive(semanticTarget.year),time:Number(semanticTarget.hour)>=0?`${String(semanticTarget.hour).padStart(2,'0')}:${String(Number(semanticTarget.minute)>=0?semanticTarget.minute:0).padStart(2,'0')}`:''};requestedTargetStart=toInstant(targetReference,sourceReference);parseReason=requestedTargetStart?'ok':'missing_target_time';}
else if(hasCancel){changeType='cancel';selectedReservationStart=direct.length===1?toInstant(direct[0]):'';parseReason='ok';sourceReference={day:positive(named?.[1]||numeric?.[1]||bareNamed?.[1]||semantic.day),month:positive(named?months[named[2]]:numeric?.[2]||semantic.month),year:positive(named?.[3]||numeric?.[3]||semantic.year),time:lexicalTimes[0]||(Number(semantic.hour)>=0?`${String(semantic.hour).padStart(2,'0')}:${String(Number(semantic.minute)>=0?semantic.minute:0).padStart(2,'0')}`:'')};}
const selectedReferenceTimes=changeType==='cancel'?[...new Set(lexicalTimes)]:sourceReference.time?[sourceReference.time]:[];
return [{json:{...input,from,messageText:message,changeType,selectedReservationStart,requestedTargetStart,selectedReferenceDay:sourceReference.day,selectedReferenceMonth:sourceReference.month,selectedReferenceYear:sourceReference.year,selectedReferenceTime:sourceReference.time,selectedReferenceTimes,parseReason}}];

const request=$('Lógica — Normalizar cambio solicitado').first().json;
