const formatLabel=value=>{const date=new Date(String(value||''));return Number.isNaN(date.getTime())?'horario sin fecha':new Intl.DateTimeFormat('es-AR',{timeZone:timezone,day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit',hour12:false}).format(date).replace(',','');};
const localParts=value=>{const [date,time]=new Intl.DateTimeFormat('en-GB',{timeZone:timezone,day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(value)).split(', ');const [day,month,year]=date.split('/').map(Number);return {day,month,year,time};};
const activeReservations=active.map(row=>({calendarId:String(row.calendarId||''),reservationEventId:String(row.reservationEventId||''),slotStart:String(row.slotStart||''),slotEnd:String(row.slotEnd||''),label:formatLabel(row.slotStart)}));
const selectedStart=String(request.selectedReservationStart||'');const selectedTimestamp=selectedStart?new Date(selectedStart).getTime():NaN;
const day=Number(request.selectedReferenceDay)>0?Number(request.selectedReferenceDay):0,month=Number(request.selectedReferenceMonth)>0?Number(request.selectedReferenceMonth):0,year=Number(request.selectedReferenceYear)>0?Number(request.selectedReferenceYear):0;
const selectedTimes=[...new Set((Array.isArray(request.selectedReferenceTimes)?request.selectedReferenceTimes:[request.selectedReferenceTime]).filter(value=>/^\d{2}:\d{2}$/.test(String(value))))];
const hasReference=Boolean(day||month||year||selectedTimes.length);
const matchesReference=row=>{const local=localParts(row.slotStart);return (!day||local.day===day)&&(!month||local.month===month)&&(!year||local.year===year)&&(!selectedTimes.length||selectedTimes.includes(local.time));};
const selectedCandidates=!Number.isNaN(selectedTimestamp)?active.filter(row=>new Date(String(row.slotStart||'')).getTime()===selectedTimestamp):hasReference?active.filter(matchesReference):[];
const matchingReservations=selectedCandidates.map(row=>({calendarId:String(row.calendarId||''),reservationEventId:String(row.reservationEventId||''),slotStart:String(row.slotStart||''),slotEnd:String(row.slotEnd||''),label:formatLabel(row.slotStart)}));
let reservation=null,reservations=[];let changeReason=String(request.parseReason||'unsupported_request');
if(request.changeType==='cancel'||request.changeType==='reschedule'){
 if(request.parseReason!=='ok')changeReason=request.parseReason;
 else if(selectedStart||hasReference){
   if(request.changeType==='cancel'&&selectedTimes.length>1&&selectedCandidates.length===selectedTimes.length){reservations=selectedCandidates;changeReason='selected_batch_by_reference';}
