   else if(selectedCandidates.length>1)changeReason='multiple_active_reservations';
   else changeReason='selected_reference_not_found';
 }else if(active.length===1){reservation=active[0];changeReason='single_active_reservation';}
 else if(active.length>1)changeReason='multiple_active_reservations';
 else changeReason='no_active_reservation';
}
const requestedTarget=new Date(String(request.requestedTargetStart||''));const hasFutureTarget=request.changeType!=='reschedule'||(!Number.isNaN(requestedTarget.getTime())&&requestedTarget.getTime()>Date.now());
if(reservation&&request.changeType==='reschedule'&&!hasFutureTarget){reservation=null;changeReason='invalid_target_time';}
const changeRoute=reservations.length>1?'cancel_batch':reservation?request.changeType:'needs_clarification';
return [{json:{...request,reservationCount:active.length,activeReservations,matchingReservations,selectedReservations:reservations.map(row=>({calendarId:String(row.calendarId||''),reservationEventId:String(row.reservationEventId||''),slotStart:String(row.slotStart||''),slotEnd:String(row.slotEnd||''),label:formatLabel(row.slotStart)})),calendarId:(reservation||reservations[0])?.calendarId||'',reservationEventId:reservation?.reservationEventId||'',reservationOfferToken:reservation?.offerToken||'',reservationSlotStart:reservation?.slotStart||reservations[0]?.slotStart||'',reservationSlotEnd:reservation?.slotEnd||reservations[0]?.slotEnd||'',requestedStart:request.requestedTargetStart||'',changeReason,change_route:changeRoute}}];

const source=$('Lógica — Seleccionar reserva activa').first().json;
