const valid=!Number.isNaN(start.getTime())&&start.getTime()>Date.now();
const format=(date)=>new Date(date.getTime()-3*60*60*1000).toISOString().slice(0,19)+'-03:00';
return [{json:{...source,requestedStart:valid?format(start):'',requestedEnd:valid?format(new Date(start.getTime()+30*60*1000)):'',offerExpiresAt:new Date(Date.now()+15*60*1000).toISOString(),timezone:'America/Argentina/Buenos_Aires',targetReservationEventId:source.reservationEventId,changeType:'reschedule',reschedule_route:valid?'offer':'needs_clarification',changeReason:valid?source.changeReason:'invalid_target_time'}}];

const source=$('Lógica — Seleccionar reserva activa').first().json;
const selected=Array.isArray(source.selectedReservations)&&source.selectedReservations.length?source.selectedReservations:source.reservationEventId?[{calendarId:source.calendarId,reservationEventId:source.reservationEventId,slotStart:source.reservationSlotStart,slotEnd:source.reservationSlotEnd,label:source.reservationSlotStart}]:[];
