if(!ids.length)throw new Error('No hay una reserva válida para preparar la cancelación.');
const batch=ids.length>1;
return [{json:{...source,calendarId:String(selected[0].calendarId||source.calendarId||''),changeType:batch?'cancel_batch':'cancel',targetReservationEventId:batch?JSON.stringify(ids):ids[0],cancellationCount:ids.length,cancellationLabels:selected.map(item=>String(item.label||item.slotStart||'horario sin fecha')),offerExpiresAt:new Date(Date.now()+15*60*1000).toISOString(),timezone:'America/Argentina/Buenos_Aires'}}];

