const state={kind:'meeting_change_selection',changeType:String(source.changeType||''),requestedTargetStart:String(source.requestedTargetStart||''),candidates:candidates.map(candidate=>({slotStart:String(candidate.slotStart||''),label:String(candidate.label||'')}))};
